import{_ as n}from"./chunks/run-changes.BxnGjCua.js";import{_ as s,C as r,o,c as i,j as t,a as h,E as l,ak as c}from"./chunks/framework.sV-XtlWr.js";const _=JSON.parse('{"title":"What changed in a run","description":"","frontmatter":{"title":"What changed in a run","lang":"en-US"},"headers":[],"relativePath":"features/run-changes.md","filePath":"features/run-changes.md","lastUpdated":1788990591000}'),d={name:"features/run-changes.md"};function u(g,e,m,p,f,b){const a=r("Needs");return o(),i("div",null,[e[0]||(e[0]=t("h1",{id:"what-changed-in-a-run",tabindex:"-1"},[h("What changed in a run "),t("a",{class:"header-anchor",href:"#what-changed-in-a-run","aria-label":'Permalink to "What changed in a run"'},"​")],-1)),l(a,{reporter:""}),e[1]||(e[1]=c('<p>The <strong>Changes</strong> tab on a run compares it against <strong>one baseline</strong> and tells you what moved: which tests newly started failing, which got fixed, and what landed between the two. It&#39;s the fastest way to answer &quot;did my push break this, or was it already red?&quot;</p><h2 id="the-baseline" tabindex="-1">The baseline <a class="header-anchor" href="#the-baseline" aria-label="Permalink to &quot;The baseline&quot;">​</a></h2><p>Every section reads the <strong>same baseline</strong>, so the &quot;new failures&quot; count is computed once and used throughout. The selector at the top says which run it is, which branch and environment that run is on, and <strong>why it was chosen</strong>.</p><p>By default the baseline is the last passing full run <strong>in the same environment</strong> — on the same branch, then on the <strong>base branch</strong> the run&#39;s branch forked from (the pull request&#39;s target branch when the reporter captured one, else the project&#39;s default branch), then on any branch — and only when the run&#39;s environment has no passing run at all does the same ladder run again across environments (see <a href="./branches.html#branch-aware-baselines">Branches</a> and <a href="/guide/concepts.html#baseline-last-green-run">Core concepts</a>). The line under the selector spells out the rung that applied, for example <em>&quot;No passing staging run exists on feature/x; the last passing run on the default branch main in staging.&quot;</em></p><p>Two ways to compare against something else:</p><ul><li><strong>Base branch</strong> — take the baseline from one branch only: its last passing run, same environment first. The list offers every branch with an earlier passing run, so it appears once the project has one to choose. Deep-linkable as <code>?baseBranch=&lt;name&gt;</code>.</li><li><strong>Run</strong> — compare against one specific run, whatever its branch or environment. Deep-linkable as <code>?baseline=&lt;runId&gt;</code>, so a link to a comparison reopens the same two runs. <strong>Previous run</strong> is the shortcut for the run just before this one.</li></ul><p><strong>Automatic</strong> returns to the default choice. The same two options exist on the API (<code>GET /api/test-runs/{id}/insights?baseBranch=…</code> / <code>?baseline=…</code>) and on the MCP <code>get_run_insights</code> tool (<code>baseBranch</code>).</p><h2 id="what-it-shows" tabindex="-1">What it shows <a class="header-anchor" href="#what-it-shows" aria-label="Permalink to &quot;What it shows&quot;">​</a></h2><ul><li><strong>New failures</strong> — passed in the baseline, failing here.</li><li><strong>Fixed</strong> — failed in the baseline, passing here.</li><li><strong>Still failing</strong> — failing in both.</li><li><strong>Newly flaky / passed on retry</strong> — passed here but needed a retry.</li><li><strong>Slower / faster</strong> — the ten largest duration changes each way.</li><li><strong>Commits since the baseline</strong> — the commit range, a copyable <code>git log</code> command and, when the SCM host is known, a link to the commits.</li><li><strong>Environment changes</strong> — the fields that differ, in <em>This run</em> / <em>Baseline</em> columns.</li></ul><figure><img src="'+n+'" alt="Run Changes tab showing the baseline selector, the tests that newly started failing, the ones that got fixed, and the commits landed since the baseline"><figcaption>The Changes tab on a run, read against one baseline — new failures, fixed tests, and the commits landed since.</figcaption></figure><p>Comparing two runs is also how the <a href="./ui-overview.html#test-run-detail">run comparison</a> works: select two runs on the project&#39;s Runs tab and the newer one opens on its Changes tab with the older as its baseline.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./branches.html#branch-aware-baselines">Branches</a> — why the default baseline is the same-branch run</li><li><a href="./flaky-tests.html">Flaky tests</a> — the per-project flaky, regression and spec-health signals</li><li><a href="./failure-clusters.html">Failure clusters &amp; the inbox</a> — the failures grouped by cause</li><li><a href="./timeline-markers.html">Timeline markers</a> — annotate the trend charts with real-world events</li></ul>',13))])}const k=s(d,[["render",u]]);export{_ as __pageData,k as default};
